"""Pure MPEG Layer III frame scanner tests, with files generated by ffmpeg."""

from __future__ import annotations

import os

import pytest

from src.api.services.media_ingest import AudioCode, InvalidAudioError, mp3_frames
from src.api.services.media_ingest.mp3_frames import (
    MAX_REJECTED_CANDIDATES,
    FrameScan,
    _frame_length,
    audible_frames,
    frames_only,
    has_xing_header,
)
from tests.audio_support import require_ffmpeg, run

pytestmark = pytest.mark.unit


@pytest.fixture(autouse=True)
def _ffmpeg() -> None:
    require_ffmpeg()


def _mp3(path, *, vbr: bool = False, write_xing: bool = True) -> bytes:
    args = [
        require_ffmpeg(),
        "-v",
        "error",
        "-y",
        "-f",
        "lavfi",
        "-i",
        "sine=frequency=440:duration=6",
        "-c:a",
        "libmp3lame",
    ]
    args += ["-q:a", "3"] if vbr else ["-b:a", "128k"]
    run(
        [
            *args,
            "-write_id3v1",
            "0",
            "-id3v2_version",
            "0",
            "-write_xing",
            "1" if write_xing else "0",
            str(path),
        ]
    )
    return path.read_bytes()


def test_clean_cbr_mp3_has_no_dropped_bytes(tmp_path) -> None:
    source = _mp3(tmp_path / "cbr.mp3")

    scan = frames_only(source)

    assert isinstance(scan, FrameScan)
    assert scan.frames == source
    assert scan.dropped_bytes == 0


def test_clean_vbr_mp3_has_no_dropped_bytes(tmp_path) -> None:
    source = _mp3(tmp_path / "vbr.mp3", vbr=True)

    scan = frames_only(source)

    assert scan.frames == source
    assert scan.dropped_bytes == 0


def test_audible_frames_drops_exactly_the_leading_xing_frame(tmp_path) -> None:
    source = frames_only(_mp3(tmp_path / "xing.mp3")).frames
    first_frame_length = _frame_length(source, 0)

    assert first_frame_length is not None
    assert has_xing_header(source)
    assert audible_frames(source) == source[first_frame_length:]
    assert not has_xing_header(audible_frames(source))


def test_audible_frames_keeps_a_stream_without_xing_unchanged(tmp_path) -> None:
    source = frames_only(_mp3(tmp_path / "no-xing.mp3", write_xing=False)).frames

    assert not has_xing_header(source)
    assert audible_frames(source) == source


def test_audible_frames_rejects_a_xing_only_stream(tmp_path) -> None:
    source = frames_only(_mp3(tmp_path / "xing-only-source.mp3")).frames
    first_frame_length = _frame_length(source, 0)

    assert first_frame_length is not None
    with pytest.raises(InvalidAudioError):
        audible_frames(source[:first_frame_length])


@pytest.mark.parametrize("where", ["start", "middle", "end"])
def test_junk_is_removed_exactly(where: str, tmp_path) -> None:
    source = frames_only(_mp3(tmp_path / f"{where}.mp3")).frames
    junk = b"arbitrary-junk-" * 68 + b"end"
    first_frame_length = _frame_length(source, 0)
    assert first_frame_length is not None
    if where == "start":
        data = junk + source
    elif where == "middle":
        data = source[:first_frame_length] + junk + source[first_frame_length:]
    else:
        data = source + junk

    scan = frames_only(data)

    assert scan.frames == source
    assert scan.dropped_bytes == len(junk)


def test_false_sync_inside_junk_is_not_a_frame(tmp_path) -> None:
    source = frames_only(_mp3(tmp_path / "false-sync.mp3")).frames
    false_sync_junk = b"junk" + b"\xff\xfb\x64\x00" + b"not-a-valid-successor" * 6
    data = false_sync_junk + source

    scan = frames_only(data)

    assert scan.frames == source
    assert scan.dropped_bytes == len(false_sync_junk)


def test_empty_input_is_invalid_audio() -> None:
    with pytest.raises(InvalidAudioError) as raised:
        frames_only(b"")

    assert raised.value.code is AudioCode.INVALID


def _synchsafe(value: int) -> bytes:
    return bytes(((value >> 21) & 0x7F, (value >> 14) & 0x7F, (value >> 7) & 0x7F, value & 0x7F))


def test_random_trailing_data_uses_few_frame_length_checks(tmp_path, monkeypatch) -> None:
    source = frames_only(_mp3(tmp_path / "random-junk.mp3")).frames
    data = source + os.urandom(10 * 1024 * 1024)
    original = mp3_frames._frame_length
    calls = 0

    def counted(data: bytes, offset: int) -> int | None:
        nonlocal calls
        calls += 1
        return original(data, offset)

    monkeypatch.setattr(mp3_frames, "_frame_length", counted)

    scan = frames_only(data)

    assert scan.frames == source
    assert calls < 10_000


def test_large_leading_id3_tag_is_skipped_before_frame_checks(tmp_path, monkeypatch) -> None:
    source = frames_only(_mp3(tmp_path / "leading-tag.mp3")).frames
    tag_body = b"x" * (5 * 1024 * 1024 - 10)
    tag = b"ID3\x04\x00\x00" + _synchsafe(len(tag_body)) + tag_body
    data = tag + source
    stream_start = len(tag)
    original = mp3_frames._frame_length
    offsets: list[int] = []

    def counted(data: bytes, offset: int) -> int | None:
        offsets.append(offset)
        return original(data, offset)

    monkeypatch.setattr(mp3_frames, "_frame_length", counted)

    scan = frames_only(data)

    assert scan.frames == source
    assert offsets[0] == stream_start
    assert all(offset >= stream_start for offset in offsets)


def test_repeated_plausible_headers_exhaust_the_rejection_budget(monkeypatch) -> None:
    data = b"\xff\xfb\x90\x00" * 200_000
    original = mp3_frames._frame_length
    calls = 0

    def counted(data: bytes, offset: int) -> int | None:
        nonlocal calls
        calls += 1
        return original(data, offset)

    monkeypatch.setattr(mp3_frames, "_frame_length", counted)

    with pytest.raises(InvalidAudioError, match="too much non-audio data"):
        frames_only(data)

    assert calls <= 2 * MAX_REJECTED_CANDIDATES + 10


def test_plausible_chain_inside_leading_id3_is_ignored(tmp_path) -> None:
    source = frames_only(_mp3(tmp_path / "tag-chain.mp3")).frames
    frame_length = _frame_length(source, 0)
    assert frame_length is not None
    body = bytearray(frame_length + 128)
    body[64:68] = b"\xff\xfb\x90\x00"
    body[64 + frame_length : 68 + frame_length] = b"\xff\xfb\x90\x00"
    tag = b"ID3\x04\x00\x00" + _synchsafe(len(body)) + body

    scan = frames_only(tag + source)

    assert scan.frames == source
    assert scan.dropped_bytes == len(tag)
